<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$params=[];$where=$u['role']==='admin'?'1=1':'p.user_id=?';if($u['role']!=='admin')$params[]=$u['id'];if(!empty($_GET['available']))$where.=" AND p.status='available'";if(!empty($_GET['status'])){$where.=' AND p.status=?';$params[]=$_GET['status'];}if(!empty($_GET['brand'])){$where.=' AND p.brand LIKE ?';$params[]='%'.$_GET['brand'].'%';}if(!empty($_GET['q'])){$where.=' AND (p.name LIKE ? OR p.unique_identifier LIKE ? OR p.brand LIKE ?)';$params[]='%'.$_GET['q'].'%';$params[]='%'.$_GET['q'].'%';$params[]='%'.$_GET['q'].'%';}$s=db()->prepare("SELECT p.*,u.full_name owner_name,u.shop_name,s.id sale_id,s.customer_name,s.customer_phone,s.sold_at,r.id return_id,r.reason return_reason,r.returned_at,r.refund_amount FROM products p JOIN users u ON u.id=p.user_id LEFT JOIN sales s ON s.product_id=p.id LEFT JOIN returns r ON r.sale_id=s.id WHERE $where ORDER BY p.created_at DESC");$s->execute($params);$rows=$s->fetchAll();foreach($rows as &$row){$row['images']=product_images((int)$row['id']);if($row['sale_id'])$row['sale_details']=['customer_name'=>$row['customer_name'],'customer_phone'=>$row['customer_phone'],'sold_at'=>$row['sold_at']];if($row['return_id'])$row['return_details']=['returned_at'=>$row['returned_at'],'reason'=>$row['return_reason'],'refund_amount'=>$row['refund_amount']];unset($row['customer_name'],$row['customer_phone'],$row['sold_at'],$row['return_reason'],$row['returned_at'],$row['refund_amount']);}out(['success'=>true,'products'=>$rows]);
